package com.example.aspect;

import org.aspectj.lang.ProceedingJoinPoint;
import org.aspectj.lang.annotation.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Component;

@Aspect
@Component
public class PerformanceLoggingAspect {

    private static final Logger log = LoggerFactory.getLogger(PerformanceLoggingAspect.class);

    @Pointcut("execution(* com.example.service.*.*(..))")
    private void servicePackageMethods() {}

    @Before("servicePackageMethods()")
    public void logBefore() {
        log.info("Entering service method execution");
    }

    @AfterReturning(pointcut = "servicePackageMethods()", returning = "result")
    public void logAfterReturning(Object result) {
        log.info("Method executed successfully with result: {}", result);
    }

    @AfterThrowing(pointcut = "servicePackageMethods()", throwing = "ex")
    public void logAfterThrowing(Exception ex) {
        log.error("Method threw exception: {}", ex.getMessage());
    }

    @Around("servicePackageMethods()")
    public Object profileMethod(ProceedingJoinPoint joinPoint) throws Throwable {
        long start = System.currentTimeMillis();
        try {
            Object output = joinPoint.proceed();
            return output;
        } finally {
            long duration = System.currentTimeMillis() - start;
            log.info("Method [{}] executed in {} ms", joinPoint.getSignature().toShortString(), duration);
        }
    }
}
